def bin_to_dec(b):
    result = 0
    for i,ch in enumerate(reversed(b)):
        if ch=='1':
            result += 1<<i  # 2**i
    return result
# Example: bin_to_dec('101101') returns 45

def simple_interest(P, R, T):
    return (P * R * T) / 100
# Example: simple_interest(10000,5,3) returns 1500

def digital_root(n):
    while n > 9:
        n = sum(int(digit) for digit in str(n))
    return n
print(digital_root(7569))

def calculate_sp(mp, discounts):
    sp = mp
    for d in discounts:
        sp *= (1 - d / 100)
    return round(sp, 2)
print(calculate_sp(1000, [20, 10]))

def equivalent_discount(d1, d2):
    return d1 + d2 - (d1 * d2) / 100
print(equivalent_discount(20, 10))

def find_mp(sp, discount):
    return sp / (1 - discount / 100)
print(find_mp(720, 28))

def calc_profit_loss(cp, sp):
    if sp > cp:
        p = ((sp - cp) / cp) * 100
        return f"Profit: {p:.2f}%"
    elif cp > sp:
        l = ((cp - sp) / cp) * 100
        return f"Loss: {l:.2f}%"
    else:
        return "No Profit, No Loss"
print(calc_profit_loss(500, 600))

def find_sp(cp, profit_pct):
    return cp * (1 + profit_pct / 100)
print(find_sp(500, 20))

